import{c as a,Q as d,j as e,m as s}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E7%BB%98%E5%9B%BE4-26.CV-KwcmR.png",b=JSON.parse('{"title":"MmadWithSparse","description":"","frontmatter":{},"headers":[{"level":1,"title":"MmadWithSparse","slug":"mmadwithsparse"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"稠密算法说明","slug":"稠密算法说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/矩阵计算/MmadWithSparse.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/矩阵计算/MmadWithSparse.md"}'),l={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/矩阵计算/MmadWithSparse.md"};function r(i,t,o,p,h,c){return d(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="mmadwithsparse" tabindex="-1">MmadWithSparse <a class="header-anchor" href="#mmadwithsparse" aria-label="Permalink to &quot;MmadWithSparse&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>完成矩阵乘加操作，传入的左矩阵A为稀疏矩阵， 右矩阵B为稠密矩阵 。对于矩阵A，在MmadWithSparse计算时完成稠密化；对于矩阵B，在计算执行前的输入数据准备时自行完成稠密化（按照下文中介绍的稠密算法进行稠密化），所以输入本接口的B矩阵为稠密矩阵。B稠密矩阵需要通过调用<a href="./../数据搬运/LoadDataWithSparse.html">LoadDataWithSparse</a>载入，同时加载索引矩阵，索引矩阵在矩阵B稠密化的过程中生成，再用于A矩阵的稠密化。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = int32_t, typename U = int8_t, typename Std::enable_if&lt;Std::is_same&lt;PrimT&lt;T&gt;, int32_t&gt;::value, bool&gt;::type = true, typename Std::enable_if&lt;Std::is_same&lt;PrimT&lt;U&gt;, int8_t&gt;::value, bool&gt;::type = true&gt;</span></span>\n<span class="line"><span>__aicore__ inline void MmadWithSparse(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; fm, const LocalTensor&lt;U&gt;&amp; filter, const MmadParams&amp; mmadParams)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>dst的数据类型。</td></tr><tr><td>U</td><td>fm、filter的数据类型。 当dst、fm、filter为基础数据类型时， T必须为int32_t类型，U必须为int8_t类型，否则编译失败。 当dst、fm、filter为TensorTrait类型时，T的LiteType必须为int32_t类型，U的LiteType必须为int8_t类型，否则编译失败。 最后两个模板参数仅用于上述数据类型检查，用户无需关注。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，结果矩阵，类型为LocalTensor，支持的TPosition为CO1。 LocalTensor的起始地址需要256个元素（1024字节）对齐。</td></tr><tr><td>fm</td><td>输入</td><td>源操作数，左矩阵A，类型为LocalTensor，支持的TPosition为A2。 LocalTensor的起始地址需要512字节对齐。</td></tr><tr><td>filter</td><td>输入</td><td>源操作数，右矩阵B，类型为LocalTensor，支持的TPosition为B2。 LocalTensor的起始地址需要512字节对齐。</td></tr><tr><td>mmadParams</td><td>输入</td><td>矩阵乘相关参数，类型为MmadParams。 具体定义请参考${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。 参数说明请参考表3。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>原始稀疏矩阵B每4个元素中应保证最多2个非零元素，如果存在3个或更多非零元素，则仅使用前2个非零元素。</p></li><li><p>当M、K、N中的任意一个值为0时，该指令不会被执行。</p></li><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li></ul><h2 id="稠密算法说明" tabindex="-1">稠密算法说明 <a class="header-anchor" href="#稠密算法说明" aria-label="Permalink to &quot;稠密算法说明&quot;">​</a></h2><p>假设原始稀疏矩阵B的每4个元素中至少有2个零，稠密化后的矩阵B是一个在每4个元素中过滤掉2个零的稠密矩阵。矩阵B稠密化的过程中生成索引矩阵，过程如下：对于稀疏矩阵B中的每4个元素，将在index矩阵中生成2个2位索引，并按照以下规则进行编码。索引必须在{0, 1, 2}范围内。</p><ul><li>第一个索引用于指示前3个元素中第1个非零元素的相对位置。</li><li>第二个索引用于指示第2个非零元素在后3个元素中的相对位置。</li></ul><p>具体可参考下表。其中，“-”表示算法不关心该位置上的值，因为其会被过滤。</p><table tabindex="0"><thead><tr><th>示例</th><th>ele0</th><th>ele1</th><th>ele2</th><th>ele3</th><th>Index_a[i]</th><th>Index_b[i]</th></tr></thead><tbody><tr><td>Two non-zero elements</td><td>0</td><td>0</td><td>X</td><td>Y</td><td>2’b10</td><td>2’b10</td></tr><tr><td>Two non-zero elements</td><td>0</td><td>X</td><td>0</td><td>Y</td><td>2’b01</td><td>2’b10</td></tr><tr><td>Two non-zero elements</td><td>X</td><td>0</td><td>0</td><td>Y</td><td>2’b00</td><td>2’b10</td></tr><tr><td>Two non-zero elements</td><td>0</td><td>X</td><td>Y</td><td>-</td><td>2’b01</td><td>2’b01</td></tr><tr><td>Two non-zero elements</td><td>X</td><td>0</td><td>Y</td><td>-</td><td>2’b00</td><td>2’b01</td></tr><tr><td>Two non-zero elements</td><td>X</td><td>Y</td><td>-</td><td>-</td><td>2’b00</td><td>2’b00</td></tr><tr><td>One non-zero element</td><td>0</td><td>0</td><td>0</td><td>X</td><td>2’b00</td><td>2’b10</td></tr><tr><td>One non-zero element</td><td>0</td><td>0</td><td>X</td><td>0</td><td>2’b10</td><td>2’b00</td></tr><tr><td>One non-zero element</td><td>0</td><td>X</td><td>0</td><td>0</td><td>2’b01</td><td>2’b00</td></tr><tr><td>One non-zero element</td><td>X</td><td>0</td><td>0</td><td>0</td><td>2’b00</td><td>2’b00</td></tr><tr><td>All zero</td><td>0</td><td>0</td><td>0</td><td>0</td><td>2’b00</td><td>2’b00</td></tr></tbody></table><p>该索引矩阵用于A矩阵的稠密化，根据索引矩阵从MatrixA中的4个元素中选择2个元素参与计算，如下图所示：</p><p><img src="'+n+`" alt=""></p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整使用样例请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/01_matrix_compute/mmad_with_sparse" target="_blank" rel="noreferrer">MmadWithSparse样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// a2Local：Mmad计算的左矩阵Tensor，TPosition位于A2</span></span>
<span class="line"><span>// b1Local/b2Local：Mmad计算的右矩阵Tensor，TPosition分别位于B1/B2</span></span>
<span class="line"><span>// idxB1Local：稀疏矩阵Tensor，TPosition位于B1</span></span>
<span class="line"><span>// cLocal：Mmad计算的输出C矩阵Tensor，TPosition位于CO1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 左矩阵A为非稀疏矩阵，右矩阵B为稠密化后的矩阵</span></span>
<span class="line"><span>// transform nz to zn, 稀疏矩阵的加载需要配合稀疏的索引和loadDataWithSparse接口进行稀疏数据加载</span></span>
<span class="line"><span>AscendC::LoadData2DParams loadDataParams;</span></span>
<span class="line"><span>loadDataParams.repeatTimes = kBlocks * nBlocks / 2;</span></span>
<span class="line"><span>loadDataParams.srcStride = 0;</span></span>
<span class="line"><span>loadDataParams.ifTranspose = false;</span></span>
<span class="line"><span>AscendC::LoadDataWithSparse(b2Local, b1Local, idxB1Local, loadDataParams);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// mmad 需要指定矩阵的维度进行计算</span></span>
<span class="line"><span>uint32 m = 16;</span></span>
<span class="line"><span>uint32 k = 64;</span></span>
<span class="line"><span>uint32 n = 16;</span></span>
<span class="line"><span>AscendC::MmadWithSparse(cLocal, a2Local, b2Local, { m, n, k, false, 0, false, false, false });</span></span></code></pre></div>`,24)])])}const _=a(l,[["render",r]]);export{b as __pageData,_ as default};
